model:
rachana: 1
sutra: sic-sector
version: 1
description: 
match: { kind: sic-sector, priority: 10 }
title: { pill: "US equities · SIC sector (computed)", id: "$.SIC", with: "$.DESCRIPTION" }
strip:
  - { label: "SIC", bind: "$.SIC", emphasis: true }
  - { label: "Industry", bind: "$.DESCRIPTION" }
  - { label: "Division", bind: "$.SECTOR" }
  - { label: "Companies", bind: "$.COMPANIES" }
  - { label: "Revenue", bind: "$.REVENUE", fmt: "compact" }
  - { label: "Net income", bind: "$.NET_INCOME", fmt: "compact", tone: "sign" }
  - { label: "Net margin", bind: "$.NET_MARGIN", fmt: "margin1", tone: "sign" }
  - { label: "Not in USD", bind: "$.NON_USD > 0 ? $.NON_USD + ' not summed' : 'None'" }
panels:
  - id: companies
    kind: table
    title: "Companies by revenue (a click opens one beside)"
    code: "COS"
    phone: { tier: "glance", from: "fragment" }
    rows: "$.ROWS"
    empty: "No companies"
    columns:
      - { label: "Ticker", bind: "@.TICKER" }
      - { label: "Company", bind: "@.NAME" }
      - { label: "Indexes", bind: "@.INDEX_TEXT" }
      - { label: "Revenue, latest FY", bind: "@.REVENUE", fmt: "compact", total: true }
      - { label: "Fiscal year", bind: "@.FISCAL_YEAR", fmt: "date" }
  - id: by-revenue
    kind: hbar
    title: "Largest by revenue, USD"
    key: "F3"
    area: right
    phone: { tier: "glance", from: "fragment", rows: 5 }
    rows: "$.BY_REVENUE"
    label: "TICKER"
    value: "REVENUE"
    fmt: "compact"
  - id: source
    kind: kv
    title: "Data source and licence"
    area: right
    phone: { tier: "must", from: "fragment" }
    rows: "$.PROVENANCE"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F9: "raw" }
